    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger 'kan' og gør ikke attestindhentning til en automatisk pligt. Fremmødeforbeholdet kræves kun, hvis fremmøde omtales, og det gør svaret ikke."
